solution.Extract.java:
import java.util.*;
import java.util.regex.*;

public final class Extract {
    private static final Pattern TAG = Pattern.compile("(?<![\\p{L}\\p{N}])#(\\w+)");
    private static final Pattern EMAIL = Pattern.compile("([\\w.+-])[\\w.+-]*@([\\w-]+(?:\\.[\\w-]+)+)");

    public static List<String> hashtags(String text) {
        Set<String> seen = new LinkedHashSet<>();
        Matcher m = TAG.matcher(text);
        while (m.find()) seen.add(m.group(1).toLowerCase());
        return new ArrayList<>(seen);
    }

    public static String maskEmails(String text) {
        return EMAIL.matcher(text).replaceAll(r -> Matcher.quoteReplacement(r.group(1) + "***@" + r.group(2)));
    }
}

unitTests:
test("hashtags in order, lower case, no duplicates", () -> {
    checkEq(Extract.hashtags("Loving #Java and #streams! #java again"), List.of("java", "streams"));
});

test("not after a letter or digit", () -> {
    checkEq(Extract.hashtags("C# and a#b are not tags, but #ok_1 is"), List.of("ok_1"));
    checkEq(Extract.hashtags("nothing here"), List.of());
});

test("emails are masked", () -> {
    checkEq(Extract.maskEmails("Write to ada.lovelace@example.com or bob@mail.example.org."),
            "Write to a***@example.com or b***@mail.example.org.");
});

test("text without emails is unchanged", () -> {
    checkEq(Extract.maskEmails("price: $5 @ noon"), "price: $5 @ noon");
});

